#!/usr/bin/env bash
#
# tung_tung_dance.sh — animation ASCII colorée (vrai RVB), generee a partir de
# la video uploadee (tung_tung.mp4), jouee dans le terminal.
#
# Usage:
#   ./tung_tung_dance.sh              # boucle infinie (Ctrl+C pour arreter)
#   ./tung_tung_dance.sh --once       # joue une seule fois
#   ./tung_tung_dance.sh --fps=15     # change la vitesse de lecture
#
set -euo pipefail

FPS=10
ONCE=0
for arg in "$@"; do
  case "$arg" in
    --once) ONCE=1 ;;
    --fps=*) FPS="${arg#*=}" ;;
    *) echo "Argument inconnu: $arg" >&2; exit 1 ;;
  esac
done

DELAY=$(awk -v fps="$FPS" 'BEGIN{printf "%f", 1/fps}')

SCRIPT_PATH="$(cd "$(dirname "$0")" && pwd)/$(basename "$0")"
ARCHIVE_LINE=$(awk '/^__ARCHIVE_BELOW__$/{print NR + 1; exit}' "$SCRIPT_PATH")

TMP_DIR="$(mktemp -d)"
cleanup() {
  printf '\033[0m\033[?25h\n'
  rm -rf "$TMP_DIR"
}
trap cleanup EXIT INT TERM

tail -n +"$ARCHIVE_LINE" "$SCRIPT_PATH" | base64 -d | gunzip > "$TMP_DIR/frames.txt"

awk -v d="$TMP_DIR" '
  BEGIN { n = 0; file = sprintf("%s/frame_%04d.txt", d, n) }
  /^%%%FRAME_SEP%%%$/ { n++; file = sprintf("%s/frame_%04d.txt", d, n); next }
  { print > file }
' "$TMP_DIR/frames.txt"

FRAMES=("$TMP_DIR"/frame_*.txt)

printf '\033[2J\033[?25l'

while true; do
  for f in "${FRAMES[@]}"; do
    printf '\033[H'
    cat "$f"
    sleep "$DELAY"
  done
  [ "$ONCE" -eq 1 ] && break
done

exit 0
